using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "";
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

if (string.IsNullOrWhiteSpace(apiKey))
{
    Console.Error.WriteLine("Set the OPENAI_API_KEY environment variable.");
    return 1;
}

var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍 Researching: {topic}\n");

// --- Build the chat client with tool support ---
IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// --- Tools ---
var notebook = new Notebook();

var tools = new AIFunction[]
{
    AIFunctionFactory.Create(
        ([Description("The search query")] string query) => WebSearchTool.SearchAsync(query),
        "web_search",
        "Searches the web for a query and returns a list of result snippets. Use this to gather information on the research topic."),

    AIFunctionFactory.Create(
        ([Description("A short title for the note")] string title,
         [Description("The note content — a fact, quote, or insight")] string content) =>
        {
            notebook.Add(title, content);
            return $"Note saved: {title}";
        },
        "take_note",
        "Saves a research note. Use this to record important facts, data points, or insights discovered during research."),

    AIFunctionFactory.Create(
        () => notebook.GetAll(),
        "read_notes",
        "Returns all notes taken so far. Use this to review what has been collected before writing the final summary."),
};

// --- Agent loop ---
var systemPrompt = $"""
    You are a research agent. Your goal is to research the following topic thoroughly and produce a well-structured summary.

    Topic: {topic}

    Instructions:
    1. Search the web multiple times with different queries to gather diverse information.
    2. Take notes on the most important facts, statistics, and insights you find.
    3. After gathering enough information (at least 3-5 searches), read your notes and write a comprehensive summary.
    4. Your final message should be the polished summary — clearly organized with sections, key findings, and a conclusion.
    """;

var messages = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt),
    new(ChatRole.User, $"Please research this topic: {topic}"),
};

var options = new ChatOptions { Tools = [.. tools] };

var response = await client.GetResponseAsync(messages, options);

Console.WriteLine("\n═══════════════════════════════════════");
Console.WriteLine("  📋  RESEARCH SUMMARY");
Console.WriteLine("═══════════════════════════════════════\n");
Console.WriteLine(response.Text);
Console.WriteLine($"\n📝 Notes collected: {notebook.Count}");

return 0;

// --- Helpers ---
static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var input = Console.ReadLine()?.Trim();
    if (string.IsNullOrWhiteSpace(input))
    {
        Console.Error.WriteLine("No topic provided.");
        Environment.Exit(1);
    }
    return input;
}

// --- Web search tool (uses Brave Search API or a fallback) ---
static class WebSearchTool
{
    private static readonly HttpClient Http = new();

    public static async Task<string> SearchAsync(string query)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        // Try Brave Search API first, fall back to DuckDuckGo instant answer API
        var braveKey = Environment.GetEnvironmentVariable("BRAVE_SEARCH_API_KEY");
        if (!string.IsNullOrWhiteSpace(braveKey))
            return await BraveSearchAsync(query, braveKey);

        return await DuckDuckGoSearchAsync(query);
    }

    private static async Task<string> BraveSearchAsync(string query, string apiKey)
    {
        var url = $"https://api.search.brave.com/res/v1/web/search?q={Uri.EscapeDataString(query)}&count=5";
        using var request = new HttpRequestMessage(HttpMethod.Get, url);
        request.Headers.Add("X-Subscription-Token", apiKey);
        request.Headers.Add("Accept", "application/json");

        var resp = await Http.SendAsync(request);
        resp.EnsureSuccessStatusCode();
        var json = await resp.Content.ReadAsStringAsync();
        var doc = JsonDocument.Parse(json);

        var results = new List<string>();
        if (doc.RootElement.TryGetProperty("web", out var web) &&
            web.TryGetProperty("results", out var items))
        {
            foreach (var item in items.EnumerateArray().Take(5))
            {
                var title = item.GetProperty("title").GetString();
                var desc = item.TryGetProperty("description", out var d) ? d.GetString() : "";
                var itemUrl = item.GetProperty("url").GetString();
                results.Add($"- {title}: {desc} ({itemUrl})");
            }
        }

        return results.Count > 0
            ? string.Join("\n", results)
            : "No results found.";
    }

    private static async Task<string> DuckDuckGoSearchAsync(string query)
    {
        var url = $"https://api.duckduckgo.com/?q={Uri.EscapeDataString(query)}&format=json&no_html=1";
        var resp = await Http.GetStringAsync(url);
        var doc = JsonDocument.Parse(resp);

        var results = new List<string>();

        if (doc.RootElement.TryGetProperty("AbstractText", out var abs) &&
            abs.GetString() is { Length: > 0 } abstractText)
        {
            results.Add($"- Summary: {abstractText}");
        }

        if (doc.RootElement.TryGetProperty("RelatedTopics", out var topics))
        {
            foreach (var t in topics.EnumerateArray().Take(5))
            {
                if (t.TryGetProperty("Text", out var text) && text.GetString() is { Length: > 0 } s)
                    results.Add($"- {s}");
            }
        }

        return results.Count > 0
            ? string.Join("\n", results)
            : $"No instant-answer results for '{query}'. Try a more specific query.";
    }
}

// --- Notebook for collecting research notes ---
class Notebook
{
    private readonly List<(string Title, string Content)> _notes = [];

    public int Count => _notes.Count;

    public void Add(string title, string content) =>
        _notes.Add((title, content));

    public string GetAll() =>
        _notes.Count == 0
            ? "No notes yet."
            : string.Join("\n\n", _notes.Select((n, i) => $"[{i + 1}] {n.Title}\n{n.Content}"));

